--初始化所有的角色
function RolesShowMgr:InitData(rolePar, cameraRootGo, maxRoleNum)
    if isNull(rolePar) or self._isInit then
        return
    end
    self:__init()
    self._isInit = true
    self._camRootGo = cameraRootGo          

    self._behaviourAction = KTool.GetOrAddComponent(rolePar.gameObject, typeof(BehaviourAction))
    self._passQuestHandler = Events.AddListener(Constants.EventNames.MainQuestPass, Bind(self, self.PassQuestHandler))
    self._mainHomeRoleActiveHandler = Events.AddListener(Constants.EventNames.MainHomeRoleActive, Bind(self, self.OnMainHomeRoleActiveHandler))
    self._mainHomeRoleActivityHandler = Events.AddListener(Constants.EventNames.MainHomeRoleActivity, Bind(self, self.OnMainHomeRoleActivity))
    self._forceChangeMainRoleStatus = Events.AddListener(Constants.EventNames.ForceChangeMainRoleStatus, Bind(self, self.OnForceChangeMainRoleStatus))

    self._unlockQuestIds = {}
    self._allRole = self:GetAllRoleCf()
    self:RefreshPermanentRoleData()
    self._maxRoleNum = maxRoleNum or 3
    self._rolePar = rolePar
    self._pollingTime = 0           
    self._wayPar = GameObject.Find("Path")

    coroutine.yield(self:RefreshShowRoles())
    self._behaviourAction.UpdateAction = function()
        self:OnUpdate()
    end
    --初始化完之后开始
    --self:SetActivityStatus(true)

    --touch事件设置 不会被模型阻挡滑动
    EasyTouch.instance.alwaysSendSwipe = true
end

