--更新常驻和不常住的角色列表
function RolesShowMgr:RefreshPermanentRoleData()
    self._permanentRoleVos = {}    
    self._notPermanentRoleVos = {}   
    self._allPosId = {}

    if isNull(self._allRole) then
        return
    end
    for k, v in pairs(self._allRole) do
        local isUnlock = GameUtils.IsUnlockedSingle(v.unlockType, v.unlockNum, v.unlockNum)
        if isUnlock then
            if self:IsPermanent(v.permanent) then
                table.insert(self._permanentRoleVos, v)
            else
                table.insert(self._notPermanentRoleVos, v)
            end
        end
        
        local poss = CfUtils.Split(v.position) 
        for k, v in pairs(poss) do
            local key = table.indexof(self._allPosId, checkNumber(v))
            if not key then
                table.insert(self._allPosId, checkNumber(v))
            end
        end
    end
end

