function RolesShowMgr:RefreshShowRoles()
    if isNull(self._rolePar) then
        return
    end
    if self._isRefreshIng then
        return
    end
    self._isRefreshIng = true 
    --self._co = cs_coroutine.start(function()

    --取一次缓存
    local t = self:GetBufferInfo()
    if t then
        self:RefreshBufferShowRoleData(t)
    else
        coroutine.yield(self:RefreshShowRoleData())         --先随机人
        coroutine.yield(self:RefreshShowRolePos())          --随机位置
    end
    coroutine.yield(self:RefreshShowRoleModel())        
        
    --清除掉不用的人物模型
    self:ClearModelBuff()
    --end)
    self._isRefreshIng = false 
end

--触发换人
function RolesShowMgr:ChangeRole(roleId)
    local co = cs_coroutine.start(function()
        --刷新一下 解锁的数据
        self:RefreshPermanentRoleData()


        roleId = checkNumber(roleId)
        if isNull(self._curShowRoleData) or roleId <= 0 then
            return false
        end
    
        local vo = self:GetRoleShowVo(roleId)
        if not vo then 
            return false
        end
    
        --先找出来下一个出现的人物
        local targetId = self:GetNextShowRoleId()

        local ind = 0
        --缓存区回收
        for k, v in pairs(self._curShowRoleData) do
            if checkNumber(roleId) == checkNumber(v._roleId) then
                v:Clear()
                ind = k
            end
        end
        if ind <= 0 then
            targetId = 0
        end
        table.remove(self._curShowRoleData, ind)
    
        print(targetId)
        --找不到的话还是原先的
        if checkNumber(targetId) <= 0 then
            targetId = roleId
        end

        local targetPosId = self:GetRoleCanShowPos(targetId)
        print(targetPosId)

        --没位置给这个用  还是拿之前的
        if checkNumber(targetPosId) <= 0 then
            targetId = roleId
            targetPosId = self:GetRoleCanShowPos(targetId)

            --正常情况这个不会出现
            if checkNumber(targetPosId) <= 0 then
                return
            end
        end
    
        vo = self:GetRoleShowVo(targetId)
        if not vo then
            return false
        end
        local roleData = RoleInstance.New()
        roleData:RefreshVo(vo, self)
        roleData:RefreshPosId(targetPosId)

        local go = self:GetModelGo(targetId)
        if go then
            KTool.SetActive(go, true)
            roleData:RefreshModelGo(go)
            roleData:RefreshPosition()
            go.transform.localPosition = Vector3(999, 999, 999)
            roleData:SetModelGoActive(true)
            roleData:SetNeedEnterId(true)

            local quickTap = KTool.GetOrAddComponent(go.gameObject, typeof(CS.HedgehogTeam.EasyTouch.QuickTap))
            if not isNull(quickTap) then
                quickTap.onTap:RemoveAllListeners()
                quickTap.onTap:AddListener(Bind(self, self.OnBtnRole, roleData._roleId))
            end
        end
    
        table.insert(self._curShowRoleData, roleData)
        self:ClearModelBuff()
        coroutine.yield(WaitForSeconds(0.1))
        if go then
            go.transform.localPosition = Vector3(0, 0, 0)
        end
    end)

    table.insert(self._allCos, co)
end

--获取一个人物可以出现的位置
function RolesShowMgr:GetRoleCanShowPos(roleId)
    roleId = checkNumber(roleId)
    if roleId <= 0 then
        return 0
    end

    --当前已经用了的所有位置
    local allRolePos = {}
    for k, v in pairs(self._curShowRoleData) do
        table.insert(allRolePos, checkString(v._posId))
    end

    local vo = self:GetRoleShowVo(roleId)
    local poss = CfUtils.Split(vo.position) 
    for k, v in pairs(poss) do
        --没有被其他人占用才让随
        if isNull(table.keyof(allRolePos, checkString(v))) then
            return v
        end
    end

    return 0
end

--找到下一个应该出现的角色
function RolesShowMgr:GetNextShowRoleId()
    if not self._permanentRoleVos then
        return 0
    elseif not self._curShowRoleData then
        return 0
    end
    local t = {}
    --优先找常驻的
    for k, v in pairs(self._permanentRoleVos) do
        local isTrue = true
        for _, data in pairs(self._curShowRoleData) do
            if checkNumber(data._roleId) == checkNumber(v.roleId) then
                isTrue = false
            end
        end
        if isTrue then
            table.insert(t, v.roleId) 
        end
    end
    --
    if table.count(t) > 0 then
        local num = math.random(table.count(t))
        return t[num]
    end

    t = {}
    --找不常住的
    for k, v in pairs(self._notPermanentRoleVos) do
        local isTrue = true
        for _, data in pairs(self._curShowRoleData) do
            if checkNumber(data._roleId) == checkNumber(v.roleId) then
                isTrue = false
            end
        end
        if isTrue then
            table.insert(t, v.roleId) 
        end
    end
    if table.count(t) > 0 then
        local num = math.random(table.count(t))
        return t[num]
    end

    return 0
end

function RolesShowMgr:RefreshBufferShowRoleData(bufferT)
    --[[
    if not isNull(self._curShowRoleData) then
        --缓存区回收
        for k, v in pairs(self._curShowRoleData) do
            self:PushModelGo(v._modelGo, v._roleId)
        end
    end
    ]]
    self._curShowRoleData = {}

    for k, v in pairs(bufferT) do
        local roleData = RoleInstance.New()
        roleData:RefreshVo(v.roleVo, self)
        roleData:RefreshPosId(v.posId)
        roleData:SetBuffEventId(v.eventId)
        table.insert(self._curShowRoleData, roleData)
    end
end

--刷新当前需要展示的角色信息
function RolesShowMgr:RefreshShowRoleData()
    --[[
    if not isNull(self._curShowRoleData) then
        --缓存区回收
        for k, v in pairs(self._curShowRoleData) do
            self:PushModelGo(v._modelGo, v._roleId)
        end
    end
    ]]
    ---@type RoleInstance[]
    self._curShowRoleData = {}
    local count = 0
    --先加常驻的
    for k, v in pairs(self._permanentRoleVos) do
        if count >= self._maxRoleNum then
            return
        end
        local isUnlock = GameUtils.IsUnlockedSingle(v.unlockType, v.unlockNum, v.unlockNum)
        if isUnlock then
            ---@type RoleInstance
            local roleData = RoleInstance.New()
            roleData:RefreshVo(v, self)
            table.insert(self._curShowRoleData, roleData)
            count = count + 1
        end
    end

    --大于最大数量直接返回
    if count >= self._maxRoleNum then
        return
    end
    local randNums = {}
    --随机个数
    local randTime = ((table.count(self._notPermanentRoleVos) > (self._maxRoleNum - count)) and (self._maxRoleNum - count) or table.count(self._notPermanentRoleVos))

    local t = {}
    for k, v in pairs(self._notPermanentRoleVos) do
        table.insert(t, k)
    end

    --所有的位置
    local allRolePos = {}

    for k = 1, randTime do
        local num = checkInt(math.random(1, table.count(t)))
        local data = self._notPermanentRoleVos[t[num]]
        if data then
            local poss = CfUtils.Split(data.position) 

            local isCan = true
            for _, v in pairs(poss) do
                if checkNumber(allRolePos[checkString(v)]) == 1 then
                    isCan = false
                    break
                end
            end

            if isCan then
                for _, v in pairs(poss) do
                    allRolePos[checkString(v)] = 1
                end

                table.insert(randNums, t[num])
            end
        end

        table.remove(t, num)
    end

    for k, v in pairs(randNums) do
        local data = self._notPermanentRoleVos[v]
        if data then
            ---@type RoleInstance
            local roleData = RoleInstance.New()
            roleData:RefreshVo(data, self)
            table.insert(self._curShowRoleData, roleData)
        end
    end
end

--刷新当前需要展示的角色位置
function RolesShowMgr:RefreshShowRolePos()
    local allRolePos = {}
    
    for k, v in pairs(self._curShowRoleData) do
        local data = v._vo
        if not isNull(data) then
            local poss = CfUtils.Split(data.position) 
            --初始化这个人可以去的位置
            local posT = {}
            for k, v in pairs(poss) do
                --没有被其他人占用才让随
                if checkNumber(allRolePos[checkString(v)]) == 0 then
                    table.insert(posT, v)
                end
            end
            
            --有可以随的位置
            if table.count(posT) > 0 then
                local num = checkInt(math.random(1, table.count(posT)))
                allRolePos[checkString(posT[num])] = 1

                --刷新位置
                v:RefreshPosId(poss[num])
            end
        end
    end
end

--刷新模型
function RolesShowMgr:RefreshShowRoleModel()
    --实例化模型
    for k, v in pairs(self._curShowRoleData) do
        local go = self:GetModelGo(v._roleId)
        if go then
            KTool.SetActive(go, true)
            v:RefreshModelGo(go)
            v:SetModelGoActive(true)
            v:RefreshPosition()

            local quickTap = KTool.GetOrAddComponent(go.gameObject, typeof(CS.HedgehogTeam.EasyTouch.QuickTap))
            if not isNull(quickTap) then
                quickTap.onTap:RemoveAllListeners()
                quickTap.onTap:AddListener(Bind(self, self.OnBtnRole, v._roleId))
            end
        end
    end
end

--点击角色
function RolesShowMgr:OnBtnRole(roleId)
