    roleInstance:OnClick()
end

function RolesShowMgr:PassQuestHandler(body)
    if isNull(body) then
        return
    end
    local questId = checkNumber(body.questId)
    if checkNumber(table.indexof(self._unlockQuestIds, questId)) > 0 then
        self:RefreshPermanentRoleData()
        self._isNeedForcedRefresh = true
    end
end

--角色显示隐藏开关
---@param body table isShow控制显示  roleid控制单个角色
function RolesShowMgr:OnMainHomeRoleActiveHandler(body)
    if isNull(body) then
        return
    end
    local isShow = checkBool(body.isShow)
    if isShow then
        self:ShowRoles(body.roleId)
        if self._isNeedForcedRefresh then
            self._isNeedForcedRefresh = false
            self._co = cs_coroutine.start(function()
                self:SetActivityStatus(false)
                local isStop = false
                local time = GameUtils.ShowBlackOverlay(nil, function()
                    while not isStop do
                        coroutine.yield(Yielders.EndOfFrame)
                    end
                end)
                coroutine.yield(WaitForSeconds(time))

                if not isNull(self._curShowRoleData) then
                    --缓存区回收
                    for k, v in pairs(self._curShowRoleData) do
                        v:Clear()
                    end
                end
                self._curShowRoleData = nil

                coroutine.yield(self:RefreshShowRoles())
                self:SetActivityStatus(isShow)
                self:ShowRoles(body.roleId)
                isStop = true
            end)
        else
            self:SetActivityStatus(isShow)
        end
    else
        self:HideRoles(body.roleId)
        self:SetActivityStatus(isShow)
    end
end

--角色活动事件开关
function RolesShowMgr:OnMainHomeRoleActivity(body)
    if isNull(body) then
        return
    end
    local isActivity = checkBool(body.isActivity)
    self:SetActivityStatus(isActivity)
end

