function RolesShowMgr:GetAllRoleCf()
    local t = CfUtils.GetCfTable(AutoIds.IdSetting1810)
    local _t = {}
    if not t then
        return _t
    end
    for k, v in pairs(t) do
        local vo = RoleShowVo.New()
        vo:FillVo(v)
        table.insert(_t, vo)
        --关卡解锁
        if checkNumber(vo.unlockType) == Constants.CommonUnlockType.PassQuest then
            table.insert(self._unlockQuestIds, checkNumber(vo.unlockNum))
        end
    end 
    return _t   
end

--清除无用的模型实例化
function RolesShowMgr:ClearModelBuff()
    if isNull(self._modelBuffer) then
        return
    end
    for k, v in pairs(self._modelBuffer) do
        if not isNull(v) then
            CS.UnityEngine.GameObject.Destroy(v)
        end
    end
    self._modelBuffer = {}
end

--模型实例化
function RolesShowMgr:PushModelGo(go, roleId)
    if isNull(self._modelBuffer) then
        self._modelBuffer = {}
    end
    if isNull(go) then
        return
    end
    KTool.SetActive(go, false)
    if not isNull(self._modelBuffer[checkString(roleId)]) then
        printError("角色模型缓存区有泄露")
    end
    self._modelBuffer[checkString(roleId)] = go
end

function RolesShowMgr:GetModelGo(roleId)
    if isNull(self._modelBuffer) then
        self._modelBuffer = {}
    end
    roleId = checkString(roleId)
    --创建
    if isNull(self._modelBuffer[roleId]) then
        local path = "Arts/Prefab_home/101008_home.prefab"
        local roleLoader = self:GetRoleLoader(path, nil, true)
        if not isNull(roleLoader) then
            local go = KTool.Instantiate(self._rolePar, roleLoader.ResultObject, true)
            if not isNull(go) then
                go.name = roleId
            end
            --self:RemoveRoleLoader(path)    --清除loader
            return go
        end
    end
    local modelGo = self._modelBuffer[roleId]
    self._modelBuffer[roleId] = nil
    return modelGo
end

---@return RoleInstance | nil
function RolesShowMgr:GetRoleInstance(roleId)
    if not self._curShowRoleData then
        self._curShowRoleData = RolesShowMgr._curShowRoleData
    end
    if not self._curShowRoleData then
        return nil
    end

    --实例化模型
    for k, v in pairs(self._curShowRoleData) do
        if checkNumber(v._roleId) == checkNumber(roleId) then
            return v
        end
    end
    return nil
end

function RolesShowMgr:PushRoleLoader(loader, path)
    if not self._roleLoaders then
        return
    end
    if not isNull(self._roleLoaders[checkString(path)]) then
        printError("角色loader pool有泄露")
    end
    self._roleLoaders[checkString(path)] = loader
end

--获取一个人物的loader
function RolesShowMgr:GetRoleLoaderByRoleId(roleId)
    local path = "Arts/Prefab_home/101008_home.prefab"
    local roleLoader = self:GetRoleLoader(path)
    return roleLoader
end

function RolesShowMgr:GetRoleLoader(path)
    if isNull(self._roleLoaders) then
        return nil
    end
    path = checkString(path)
    --创建
    if isNull(self._roleLoaders[path]) then
        local roleLoader = ResourceModule.LoadBundleAsync(path, nil, true)
        while not roleLoader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end
        if roleLoader.IsSuccess then
            self:PushRoleLoader(roleLoader, path) 
        else
            roleLoader:Release()
            return nil
        end
        return roleLoader
    end
    return self._roleLoaders[path]
end

--清掉loader
function RolesShowMgr:RemoveRoleLoader(path)
    if not self._roleLoaders then
        return
    end
    if isNull(self._roleLoaders[checkString(path)]) then
        return
    end
    self._roleLoaders[checkString(path)]:Release()
end

