--提示信息go的loader
function RolesShowMgr:GetTipsGoLoader(type)
    if isNull(self._tipsGoLoaders) then
        self._tipsGoLoaders = {}
    end
    type = checkString(type)
    --创建
    if isNull(self._tipsGoLoaders[type]) then
        local path = string.format("Arts/Prefab_home/100_bubble0%s.prefab", type)
        local loader = ResourceModule.LoadBundleSync(path)
        
        if loader.IsSuccess then
            self:PushTipsGoLoader(loader, type) 
        else
            loader:Release()
            return nil
        end

        return loader
    end
    return self._tipsGoLoaders[type]
end

--是否是常驻
function RolesShowMgr:IsPermanent(type)
    return checkNumber(type) == ExistStatus.Permanent
end

function RolesShowMgr:HideRoles(roleId)
    if not self._curShowRoleData then
        return
    end

    for k, v in pairs(self._curShowRoleData) do
        if roleId then
            if checkNumber(roleId) ~= checkNumber(v._roleId) then
                v:SetModelGoActive(false)
            end
        else
            v:SetModelGoActive(false)
        end
        v:SetCurTipsGoActive(false)
    end
end

function RolesShowMgr:ShowRoles(roleId)
    if not self._curShowRoleData then
        return
    end
    
    for k, v in pairs(self._curShowRoleData) do
        if roleId then
            if checkNumber(roleId) == checkNumber(v._roleId) then
                v:SetModelGoActive(true)
                break
            end
        else
            v:SetModelGoActive(true)
        end
        v:SetCurTipsGoActive(true)
    end
end

function RolesShowMgr:OnUpdate()
    --强制停止循环
    if not self._isAutoActivity then
        return
    elseif not self._curShowRoleData then
        return
    elseif checkNumber(KCookie.Get('QTEShow')) == 1 then
        self._isHasQteShow = true      --这次有qte
        return
    end

    for k, v in pairs(self._curShowRoleData) do
        --一秒轮询一次
        if self._pollingTime > 1 then
            --[[
            --不在互动中 重新随
            if not v:IsInteractive() and v:IsCanRandEvent() then
                local t = self:GetRoleAllEvents(v._roleId)
                local num = math.random(#t)
                local eventId = t[num]
                v:PlayEventById(eventId)
            end
            self._pollingTime = 0
            ]]
        else
            self._pollingTime = self._pollingTime + CS.UnityEngine.Time.deltaTime
        end

        v:OnUpdate()
    end
end

--获取一个没人的位置
function RolesShowMgr:GetFreePos(id)
    if not self._allPosId or not self._curShowRoleData then
        return 0
    end

    local curUsePoss = {}
    for k, v in pairs(self._curShowRoleData) do
        table.insert(curUsePoss, checkNumber(v._posId))
    end

    for k, v in pairs(self._allPosId) do
        local key = table.indexof(curUsePoss, checkNumber(v))
        if not key then
            return v
        end
    end
    return 0
end

--获取路线
function RolesShowMgr:GetWayCinemachineSmoothPath(fPosId, tPosId)
    fPosId = checkNumber(fPosId)
    tPosId = checkNumber(tPosId)

    local normal = 1
    if not self._allWay then
        self._allWay = {}
    end

    local wayName = fPosId.."-"..tPosId
    --默认路径是小id_大id
    if fPosId > tPosId then
        normal = -1
        wayName = tPosId.."-"..fPosId
    end

    --先取缓存
    local data = self._allWay[wayName]
    if isNull(data) then 
        local go = self._wayPar.transform:Find(wayName)
        if not go then
            return nil, normal
        end

        local cinemachineSmoothPath = go:GetComponent(typeof(CinemachineSmoothPath))
        self._allWay[wayName] = cinemachineSmoothPath
    end
    return self._allWay[wayName], normal
end

function RolesShowMgr:GetRoleShowVo(id)
    id = checkNumber(id)
    if id <= 0 then
        return nil
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting1810, "RoleShowVo", id)
    return vo
end

--获取交互的相机
function RolesShowMgr:GetInteractiveCam(name)
    if not self._camRootGo then
        return nil
    end
    local go = self._camRootGo.transform:Find(name)        
    return go
end

--设置相机的影藏和显示
function RolesShowMgr:SetCameraActivity(isShow, camName, isNotPd)
    local go = self:GetInteractiveCam(camName)
    if not go then
        return
    end
    isShow = checkBool(isShow)
    local mainCamDefalultBlendNum = 1
    if isShow then
        mainCamDefalultBlendNum = 0
    end
    CfUtils.ChangeMainCamDefalultBlend(mainCamDefalultBlendNum)

    if isShow then
        self:SetMainHomeCameraActivity(false)
    end

    KTool.SetActive(go, isShow)
    if not checkBool(isNotPd) then
        --[[
        local pd = KTool.GetComponent(go.gameObject, typeof(CS.UnityEngine.Playables.PlayableDirector))
        if pd then
            coroutine.yield(CS.UnityEngine.WaitForSeconds(pd.duration))
        end
        ]]
        coroutine.yield(0.5)
    end
end

--设置主场景相机  特殊处理
function RolesShowMgr:SetMainHomeCameraActivity(isShow)
    isShow = checkBool(isShow)
    local go = self:GetInteractiveCam("Rolling")
    if not go then
        return
    end

    KTool.SetActive(go, isShow)
end

--设置离开时的缓存信息
function RolesShowMgr:SetBufferInfo()
    self._buffer = {}
    for k, v in pairs(self._curShowRoleData) do
        local eventId = 0
        if v._curEventVo then
            eventId = v._curEventVo.id
        else
            --取一次缓存
            eventId = checkNumber(v:GetBuffEventId())
        end
        table.insert(self._buffer, {
            roleVo = v._vo,
            posId = v._posId,
            eventId = eventId
        })
    end
end

function RolesShowMgr:GetBufferInfo()
    local t = clone(self._buffer)
    self._buffer = nil 
    return t
end

