    end
    return self._coffeeGos[path]
end

function RolesShowMgr:PushCoffeeGo(go, path)
    if isNull(go) then
        return
    end
    if not self._coffeeGos then
        self._coffeeGos = {}
    end
    self._coffeeGos[checkString(path)] = go
