function RolesShowMgr:ClearCoffeeLoaderAndGo()
    if not isNull(self._coffeeLoaders) then
        for k, v in pairs(self._coffeeLoaders) do
            v:Release(true)
        end
    end
    self._coffeeLoaders = {}
    if not isNull(self._coffeeGos) then
        xTry(function()
            for k, v in pairs(self._coffeeGos) do
                --临时lua层释放 CriLipsDeformerForAtomSource atomAnalyzer
                local lip = v:GetComponent(typeof(CriLipsDeformerForAtomSource))
                if not isNull(lip) and not isNull(lip.atomAnalyzer) then
                    lip.atomAnalyzer:Dispose()
                end

                GameObject.Destroy(v)
            end
        end)
    end
    self._coffeeGos = {}
end
