--获取初次进入时候得事件id
function RolesShowMgr:GetEnterEventId(roleId)
    roleId = checkNumber(roleId)
    if roleId <= 0 then
        return 0
    end
    local vo = self:GetRoleShowVo(roleId)
    if not vo then
        return 0
    end
    local t = CfUtils.Split(vo.enterAin)
    if not t then
        return 0
    end
    return t[math.random(1, table.count(t))]
end

