function RolesShowMgr:Clear()
    if checkNumber(KCookie.Get("IsNeedRefreshInteraction")) == 1 then
        self:SetBufferInfo()
    end

    Events.RemoveListener(Constants.EventNames.MainQuestPass, self._passQuestHandler)
    Events.RemoveListener(Constants.EventNames.MainHomeRoleActive, self._mainHomeRoleActiveHandler)
    Events.RemoveListener(Constants.EventNames.MainHomeRoleActivity, self._mainHomeRoleActivityHandler)
    Events.RemoveListener(Constants.EventNames.ForceChangeMainRoleStatus, self._forceChangeMainRoleStatus)

    if not isNull(self) then
        if not isNull(self._behaviourAction) then
            self._behaviourAction.UpdateAction = nil
        end
        if not isNull(self._roleLoaders) then
            for k, v in pairs(self._roleLoaders) do
                v:Release(true)
            end
            self:ClearModelBuff()
        end
        if not isNull(self._timeLineLoaders) then
            for k, v in pairs(self._timeLineLoaders) do
                v:Release(true)
            end
        end
        if not isNull(self._tipsGoLoaders) then
            for k, v in pairs(self._tipsGoLoaders) do
                v:Release(true)
            end
        end
        if not isNull(self._roleTalkGoLoader) then
            self._roleTalkGoLoader:Release(true)
        end

        if self._co then
            cs_coroutine.stop(self._co)
            self._co = nil
        end

        if self._allCos then
            for k, v in pairs(self._allCos) do
                if not isNull(v) then
                    cs_coroutine.stop(v) 
                end
            end
            self._allCos = nil
        end
        if self._curShowRoleData then
            for k, v in pairs(self._curShowRoleData) do
                v:Clear()
            end
        end
    end
    EasyTouch.instance.alwaysSendSwipe = false

    self:__delete()
    self.Destroy(self)   --这个好像没用
end

return RolesShowMgr